import java.util.Scanner;

public class RailwayTicket {
    // Data members
    private String name;
    private String coach;
    private long mobno;
    private int amt;
    private double totalamt;

    // Method to accept passenger details
    public void accept() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Passenger Name: ");
        name = sc.nextLine();
        System.out.print("Enter Coach Type (First_AC / Second_AC / Third_AC / Sleeper): ");
        coach = sc.next();
        System.out.print("Enter Mobile Number: ");
        mobno = sc.nextLong();
        System.out.print("Enter Basic Ticket Amount (Rs.): ");
        amt = sc.nextInt();
    }

    // Method to calculate total ticket amount
    public void update() {
        if (coach.equalsIgnoreCase("First_AC")) {
            totalamt = amt + 700;
        } else if (coach.equalsIgnoreCase("Second_AC")) {
            totalamt = amt + 500;
        } else if (coach.equalsIgnoreCase("Third_AC")) {
            totalamt = amt + 250;
        } else if (coach.equalsIgnoreCase("Sleeper")) {
            totalamt = amt;
        } else {
            System.out.println("Invalid coach type! Standard rate applied.");
            totalamt = amt;
        }
    }

    // Method to display passenger ticket details
    public void display() {
        System.out.println("\n========================================");
        System.out.println("          RAILWAY RESERVATION TICKET     ");
        System.out.println("========================================");
        System.out.println("Passenger Name : " + name);
        System.out.println("Coach Type     : " + coach);
        System.out.println("Mobile Number  : " + mobno);
        System.out.printf("Total Amount   : Rs. %.2f\n", totalamt);
        System.out.println("========================================");
    }

    // Main method
    public static void main(String[] args) {
        RailwayTicket passenger = new RailwayTicket();
        passenger.accept();
        passenger.update();
        passenger.display();
    }
}
