import java.util.Scanner;

public class BubbleSortAndBinarySearch {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = 15;
        int[] arr = new int[n];

        System.out.println("Enter 15 integers:");
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        // 1. Bubble Sort (Ascending Order)
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - 1 - i; j++) {
                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }

        // 2. Display Sorted Array
        System.out.println("\nSorted Array (Ascending Order):");
        for (int num : arr) {
            System.out.print(num + " ");
        }
        System.out.println();

        // 3. Binary Search
        System.out.print("\nEnter integer to search: ");
        int key = sc.nextInt();

        int low = 0, high = n - 1;
        int pos = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid] == key) {
                pos = mid;
                break;
            } else if (arr[mid] < key) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        if (pos != -1) {
            System.out.println("Search Successful. Element found at index: " + pos + " (Position: " + (pos + 1) + ")");
        } else {
            System.out.println("Search Unsuccessful. Element not found.");
        }

        sc.close();
    }
}
```

### Variable Description Table (VDT):
| Variable Name | Data Type | Purpose / Description |
| :--- | :--- | :--- |
| `n` | `int` | Array size (15) |
| `arr` | `int[]` | Array to store 15 integers |
| `i`, `j` | `int` | Loop indices for Bubble Sort passes |
| `temp` | `int` | Temporary swap variable |
| `key` | `int` | Target integer entered by user for search |
| `low`, `high`, `mid` | `int` | Binary search boundaries and midpoint |
| `pos` | `int` | Index of key if found (-1 otherwise) |

