import java.util.Scanner;

public class SentenceAnalysis {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence:");
        String sentence = sc.nextLine().trim();

        if (sentence.isEmpty()) {
            System.out.println("Empty input sentence.");
            return;
        }

        String upperStr = sentence.toUpperCase();
        String[] words = upperStr.split("\\s+");
        int totalWords = words.length;

        int vowelStartWords = 0;
        for (String w : words) {
            char first = w.charAt(0);
            if (first == 'A' || first == 'E' || first == 'I' || first == 'O' || first == 'U') {
                vowelStartWords++;
            }
        }

        // Reverse order of words
        StringBuilder reversed = new StringBuilder();
        for (int i = words.length - 1; i >= 0; i--) {
            reversed.append(words[i]);
            if (i > 0) {
                reversed.append(" ");
            }
        }

        System.out.println("\n--- Sentence Analysis ---");
        System.out.println("Total Words: " + totalWords);
        System.out.println("Words beginning with a vowel: " + vowelStartWords);
        System.out.println("Words in reverse order: " + reversed.toString());

        sc.close();
    }
}
```

