import java.util.Scanner;

public class MatrixDiagonalsAndSymmetry {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = 4;
        int[][] mat = new int[n][n];

        System.out.println("Enter 16 integers for a 4x4 matrix:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = sc.nextInt();
            }
        }

        // 1. Display matrix
        System.out.println("\n--- 4x4 Matrix ---");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.print(mat[i][j] + "\t");
            }
            System.out.println();
        }

        int leftSum = 0;
        int rightSum = 0;
        boolean isSymmetric = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) {
                    leftSum += mat[i][j];
                }
                if (i + j == n - 1) {
                    rightSum += mat[i][j];
                }
                if (mat[i][j] != mat[j][i]) {
                    isSymmetric = false;
                }
            }
        }

        System.out.println("\nSum of Left (Principal) Diagonal  = " + leftSum);
        System.out.println("Sum of Right (Secondary) Diagonal = " + rightSum);
        if (isSymmetric) {
            System.out.println("The matrix is a SYMMETRIC MATRIX.");
        } else {
            System.out.println("The matrix is NOT a Symmetric Matrix.");
        }

        sc.close();
    }
}
```

