public class OverloadCalculate {
    // Method 1: Square or Cube of an integer
    public void calculate(int n, char ch) {
        if (ch == 's' || ch == 'S') {
            System.out.println("Square of " + n + " = " + (n * n));
        } else if (ch == 'c' || ch == 'C') {
            System.out.println("Cube of " + n + " = " + (n * n * n));
        } else {
            System.out.println("Invalid Choice: " + ch);
        }
    }

    // Method 2: Product or Absolute difference of two doubles
    public void calculate(double a, double b, char ch) {
        if (ch == 'p' || ch == 'P') {
            System.out.println("Product of " + a + " and " + b + " = " + (a * b));
        } else {
            double diff = Math.abs(a - b);
            System.out.println("Absolute difference between " + a + " and " + b + " = " + diff);
        }
    }

    // Method 3: Frequency of character in string
    public void calculate(String str, char ch) {
        int freq = 0;
        for (int i = 0; i < str.length(); i++) {
            if (str.charAt(i) == ch) {
                freq++;
            }
        }
        System.out.println("Frequency of '" + ch + "' in \"" + str + "\" = " + freq);
    }

    public static void main(String[] args) {
        OverloadCalculate obj = new OverloadCalculate();

        System.out.println("--- Call 1: calculate(5, 'S') ---");
        obj.calculate(5, 'S');
        obj.calculate(3, 'c');

        System.out.println("\n--- Call 2: calculate(12.5, 4.0, 'p') ---");
        obj.calculate(12.5, 4.0, 'p');
        obj.calculate(50.0, 75.5, 'd');

        System.out.println("\n--- Call 3: calculate(\"MATHEMATICS\", 'M') ---");
        obj.calculate("MATHEMATICS", 'M');
    }
}
```

